import{_ as t,o as i,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Service Status","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/service-status.md","filePath":"user-guide/settings/service-status.md","lastUpdated":1787586465000}'),o={name:"user-guide/settings/service-status.md"};function n(s,e,l,c,g,d){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="service-status" tabindex="-1">Service Status <a class="header-anchor" href="#service-status" aria-label="Permalink to &quot;Service Status&quot;">​</a></h1><p>The Service Status page monitors the health of Lertaro&#39;s background indexing service and provides real-time log viewers across the Service, App, and Hook processes. The page is located at <strong>Settings → Service Status</strong>.</p><h2 id="_1-service-control-status-card" tabindex="-1">1. Service Control &amp; Status Card <a class="header-anchor" href="#_1-service-control-status-card" aria-label="Permalink to &quot;1. Service Control &amp; Status Card&quot;">​</a></h2><p>The top card displays real-time health metrics of the elevated Windows indexing service:</p><ul><li><strong>State Indicators</strong>: <ul><li><strong>Ready</strong>: Service is healthy and operational, displaying live counts of indexed files and folders.</li><li><strong>Indexing</strong>: An initial scan or incremental index rebuild is in progress, accompanied by a dynamic progress spinner.</li><li><strong>Installing</strong>: Registering and launching the background Windows service.</li><li><strong>Error</strong>: The service is offline or encountered a critical fault, showing error descriptions and an alert badge.</li></ul></li><li><strong>Self-Healing &amp; Installation</strong>: An <strong>Install and Start Service</strong> button appears exclusively when the service is missing or in an error state. During normal operation, the service runs continuously in the background.</li></ul><h2 id="_2-multi-process-live-log-viewer" tabindex="-1">2. Multi-Process Live Log Viewer <a class="header-anchor" href="#_2-multi-process-live-log-viewer" aria-label="Permalink to &quot;2. Multi-Process Live Log Viewer&quot;">​</a></h2><p>The integrated log viewer below is split into three dedicated tabs mapping to Lertaro&#39;s three active processes:</p><ul><li><strong>App Tab</strong>: Logs user interactions, search queries, UI rendering, and hotkey activations from the foreground WPF application.</li><li><strong>Hook Tab</strong>: Logs low-level keyboard hook events and isolation states from the hook process (<code>Lertaro.Hook.exe</code>).</li><li><strong>Service Tab</strong>: Logs USN change journal parsing, filesystem scanning, in-memory tree building, and IPC communications from the background service (<code>Lertaro.Service.exe</code>).</li></ul><h3 id="filtering-log-maintenance" tabindex="-1">Filtering &amp; Log Maintenance <a class="header-anchor" href="#filtering-log-maintenance" aria-label="Permalink to &quot;Filtering &amp; Log Maintenance&quot;">​</a></h3><ul><li><strong>Level Filtering</strong>: Dropdown filtering by &quot;All / Error / Warning / Information / Debug&quot;, with color-coded log lines.</li><li><strong>Keyword Search</strong>: Type text into the search box to filter log lines in real-time, combining additively with level filters.</li><li><strong>Safe Log Clearing</strong>: Click <strong>Clear Logs</strong> to truncate logs for the active tab. Clearing the Service tab is handled safely via IPC proxy without requiring administrative elevation.</li></ul>',10)])])}const p=t(o,[["render",n]]);export{h as __pageData,p as default};
